add('reviews.html','Pixelalty Customer Reviews | Real Customer Experiences','Read approved Pixelalty customer reviews for website design and listing video services. Verified Customer badges are applied only after manual verification.',f'''<section class="page-hero wrap"><p class="eyebrow">CUSTOMER EXPERIENCES</p><h1>Real projects.<br><span class="muted">Honest perspectives.</span></h1><div class="hero-bottom"><div><h2 class="review-page-title">Pixelalty Customer Reviews</h2><p class="lead">Experiences shared by customers, reviewed before publication.</p></div>{btn('Leave a review','review.html',True)}</div></section><section class="wrap section-tight"><div class="filter-bar" role="group" aria-label="Filter customer reviews"><button class="filter active" data-filter="all" aria-pressed="true">All</button><button class="filter" data-filter="web" aria-pressed="false">Web Design</button><button class="filter" data-filter="listing" aria-pressed="false">Listing Video</button></div><div data-reviews class="reviews-grid"><p class="empty-state">Customer reviews are being prepared.</p></div><button class="button button-secondary load-more" data-load-more hidden>Load more reviews</button><noscript><p>Enable JavaScript to load current customer reviews.</p></noscript><div class="review-integrity"><h2>A note on reviews</h2><p>Reviews are moderated for genuine experience, spam, privacy, and relevance. Positive and negative feedback are welcome. Ratings and customer words are not rewritten. A Verified Customer badge means Pixelalty has manually matched the reviewer to business records; it is not automatic.</p><p>The homepage may feature a selection of reviews. This page shows published reviews, newest first.</p></div></section>{cta()}''','reviews.js')
