legal_source=json.loads((ROOT/'tools/legal_content.json').read_text(encoding='utf-8'))
legal=legal_source['pages']
def legal_text(value):
 parts=[]
 cursor=0
 for match in re.finditer(r'\[([^\[\]]+)\]\((https://[^\s<>"()]+)\)', value):
  parts.append(escape(value[cursor:match.start()]))
  label,url=match.groups()
  parts.append(f'<a href="{escape(url,quote=True)}">{escape(label)}</a>')
  cursor=match.end()
 parts.append(escape(value[cursor:]))
 return ''.join(parts)

def legal_block(block):
 if block['type']=='p':
  return '<p>'+legal_text(block['text'])+'</p>'
 if block['type']=='ul':
  return '<ul>'+''.join('<li><p>'+legal_text(item)+'</p></li>' for item in block['items'])+'</ul>'
 raise ValueError('Unsupported legal content block: '+str(block['type']))

for file,page in legal.items():
 title,desc,sections=page['title'],page['description'],page['sections']
 toc=''.join(f'<a href="#section-{i}">{escape(section["title"])}</a>' for i,section in enumerate(sections,1))
 content=''.join(f'<section id="section-{i}"><h2><span>{i:02}</span> {escape(section["title"])}</h2>'+''.join(legal_block(block) for block in section['blocks'])+'</section>' for i,section in enumerate(sections,1))
 body=f'<section class="page-hero wrap legal-hero"><p class="eyebrow">PIXELALTY / POLICIES</p><h1>{escape(title)}</h1><p class="lead">{escape(desc)}</p><p class="small">Last updated: {escape(legal_source["updated"])}</p></section><div class="wrap legal-layout"><nav class="legal-toc" aria-label="On this page"><p class="eyebrow">ON THIS PAGE</p>'+toc+'</nav><article class="legal-copy">'+content+'<div class="legal-links"><a href="https://pixelalty.com">Pixelalty home</a><a href="https://pixelalty.com/terms">Terms</a><a href="https://pixelalty.com/privacy">Privacy</a><a href="https://pixelalty.com/refund-policy">Refund policy</a><a href="https://pixelalty.com/contact">Contact Pixelalty</a><a href="https://www.instagram.com/pixelalty/">Instagram</a></div></article></div>'
 add(file,title+' | Pixelalty',desc,body)

